pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base cost: The tighter the fit, the better (Best-Fit principle).
    let mut score = post_residual as f64;

    // 2. Penalize opening a new bin prematurely.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have no other options (fitting_bins_count == 0)
        // or if the current mean_residual is already very low, suggesting we should preserve it.
        score += 150.0 - (fitting_bins_count as f64 * 50.0);
    } else {
        // 3. Lookahead Logic: If the next item fits into the post_residual,
        // we heavily reward this bin to keep the packing density high.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
            // Additional reward if the next item perfectly fills the residual
            if post_residual == next_item_size {
                score -= 30.0;
            }
        }

        // 4. Penalty for "orphaning" bins: 
        // If this is the last bin that can fit the item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // 5. Global state normalization:
        // Penalize higher mean_residual to push the algorithm towards compacting existing bins.
        score += mean_residual * 0.1;

        // 6. Progress factor:
        // Be more aggressive in packing as we near the end of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize post_residuals that are below the global mean_residual as they increase fragmentation.
    if post > 0.0 && post < mean_residual {
        score += (mean_residual - post).powf(1.5);
    }

    // Lookahead logic: If the next item is large and won't fit in this post_residual, 
    // penalize this bin to preserve it for smaller items or force a better fit.
    if next_item_size > post_residual && next_item_size > 0 {
        score += (next_item_size as f64 - post) * 1.2;
    }

    // Dynamic thresholding based on stream progress. 
    // As the stream nears the end, we become more aggressive about filling bins (Best Fit).
    // Early in the stream, we are more cautious about creating tight, unusable residuals.
    let tightness_penalty = (1.0 - progress) * (bin_capacity as f64 - post).powf(1.2);
    score += tightness_penalty;

    // If this is the only bin that fits, reduce the penalty to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Special handling for the "New Bin" candidate (bin_residual == bin_capacity).
    // We make it expensive early on, but cheaper if all existing bins result in high fragmentation.
    if bin_residual == bin_capacity {
        score = 80.0 + (progress * 20.0) + (mean_residual * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // The core objective is to minimize post_residual (Best Fit), but we apply 
    // a non-linear penalty for creating "fragmented" space (small residues that 
    // are unlikely to fit future items).

    // Penalty for creating a bin that is almost full but not quite (1-9 range)
    // as these are notoriously difficult to fill in later steps.
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Lookahead logic: if next_item_size is large, we want to preserve bins 
    // that have enough capacity to hold it.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.5
    } else {
        0.0
    };

    // Dynamic threshold: As the stream progresses, we become more conservative 
    // about opening new bins vs filling existing ones.
    let new_bin_bias = if bin_residual == bin_capacity {
        // High cost to open a new bin early, but decreases as we reach the end
        // to ensure we don't end up with many half-empty bins at the finish.
        15.0 + (progress * 20.0)
    } else {
        0.0
    };

    // Encourage filling bins that are already closer to the mean_residual
    // to maintain uniformity across open bins.
    let uniformity_bonus = (post - mean_residual).abs() * 0.5;

    let score = post + fragmentation_penalty + lookahead_penalty + new_bin_bias + uniformity_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle).
    let mut score = post;

    // Penalty for creating "slivers" (small, unusable residuals) that are smaller than the next item.
    // If the next item is larger than the post_residual, this bin becomes dead space for that item.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 1.5;
    }

    // Dynamic thresholding: Near the end of the stream, prioritize closing bins to reduce the total count.
    // We penalize opening new bins more heavily as we approach the end of the stream.
    if bin_residual == bin_capacity {
        score += 15.0 + (progress * 40.0);
    }

    // Coupling: If there is only one fitting bin, reward using it to avoid opening a new bin.
    // We use a non-linear decay based on the mean residual to keep bins balanced.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= (100.0 - mean_residual) * 0.2;
    }

    // Non-linear interaction: penalize leaving large gaps when progress is high,
    // as large gaps are harder to fill late in the stream.
    score += (post * post / 100.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base cost: The remaining space in the bin (post_residual).
    // 2. Penalty for creating "dead space": If post_residual is small but > 0, 
    //    it's often worse than having 0 residual (perfect fit).
    let mut score = post_residual as f64;

    // 3. Lookahead Logic: If the next item fits into the post_residual, 
    //    heavily favor this bin (negative score).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Distribution Balancing: Penalize bins that deviate significantly from the mean_residual.
    //    This helps keep bins filled relatively evenly to maximize future packing options.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. New Bin Penalty: If bin_residual == bin_capacity, this is a "new bin" candidate.
    //    We only want to open a new bin if the existing fits are very poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current number of bins is low or 
        // if the current fits are extremely inefficient (high mean_residual).
        score += 45.0; 
        score -= (open_bins_count as f64) * 0.5;
    } else {
        // 6. Urgency: If this is the last fitting bin, prioritize it to avoid opening a new one unnecessarily.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 7. Progress Weighting: As the stream nears the end, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

