pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We penalize high post_residual to encourage tight packing
    let mut score = post;

    // Non-linear penalty for creating "dead space" that is likely too small for future items
    // If the post_residual is small but > 0, it's often wasted space.
    // We increase score (penalize) if post_residual is in the 1-15 range (fragile).
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * 2.5;
    }

    // Lookahead coupling: If next_item_size is large, penalize small residuals in the current bin
    // that would "starve" the next item.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if (post < next_f) && (post > 0.0) {
            score += (next_f - post) * 1.5;
        }
    }

    // Dynamic thresholding based on stream progression:
    // Early in the stream, be more aggressive with packing (lower score).
    // Late in the stream, favor opening a new bin if the fit is poor to avoid fragmentation.
    let exhaustion_factor = progress.powf(2.0) * 20.0;
    score += exhaustion_factor * (post / bin_capacity as f64);

    // If this is the only fitting bin, reward it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalty for empty bins (the "New Bin" candidate)
    // Only open if the "best" existing bin is extremely inefficient.
    if bin_residual == bin_capacity {
        score += 25.0 + (mean_residual * 0.5);
    }

    score
}
